import math

def mel(f):
    return 2595 * math.log10(1 + f / 700)

pairs = [(100, 200), (1000, 1100), (4000, 4100)]
for f1, f2 in pairs:
    m1, m2 = mel(f1), mel(f2)
    print(f'{f1}Hz -> {f2}Hz  (100Hz gap):  Mel change = {m2 - m1:.2f}')

print('\nNotice: identical 100Hz gaps produce very different Mel-scale changes')
print('depending on where they fall in the spectrum -- this mirrors human hearing.')

