# Verification: SHA-256 hash of content + ECDSA signature checked against issuer's public key

import hashlib

def content_hash(data):
    return hashlib.sha256(data.encode()).hexdigest()

def verify(content, manifest):
    if manifest is None:
        return 'NO MANIFEST -- cannot verify provenance either way'
    if content_hash(content) == manifest['content_hash']:
        return 'VERIFIED -- content matches manifest, unmodified since creation'
    return 'TAMPERED -- content hash does not match manifest -- modified after signing'

original = 'a photo of a public statement, unaltered'
manifest = {'content_hash': content_hash(original), 'issuer': 'TrustedCameraCo'}

tampered = 'a photo of a public statement, DIGITALLY ALTERED'

print('Unmodified content:', verify(original, manifest))
print('Tampered content:  ', verify(tampered, manifest))
print('No manifest at all:', verify(tampered, None))
